mapper.select:
select c.id as goodsCategoryId,c.name as goodsCategoryName, ROUND(AVG(r.max_price),2) as maxPriceAvg, ROUND(AVG(r.mid_price),2) as midPriceAvg, ROUND(AVG(r.min_price),2) as minPriceAvg from market_goods_category c left join goods_pricing_record r on c.id = r.goods_category_id where c.deleted = 0
and c.id in
#{goodsCategoryId}
and r.create_time >= #{param.period.begin}
and r.create_time < #{param.period.end}
GROUP BY c.id ORDER BY midPriceAvg desc

SELECT c.id AS goodsCategoryId,c.name AS goodsCategoryName,DATE_FORMAT(r.create_time,#{param.groupDateFormat}) as date, ROUND(AVG(r.max_price),2) AS maxPriceAvg, ROUND(AVG(r.mid_price),2) AS midPriceAvg, ROUND(AVG(r.min_price),2) AS minPriceAvg FROM market_goods_category c LEFT JOIN goods_pricing_record r ON c.id = r.goods_category_id WHERE c.deleted = 0
and c.id in
#{goodsCategoryId}
and c.name like concat('%',#{param.goodsCategoryName},'%')
and r.create_time >= #{param.period.begin}
and r.create_time < #{param.period.end}
GROUP BY c.id,DATE_FORMAT(r.create_time,#{param.groupDateFormat}) ORDER BY midPriceAvg desc

mapper.sql:
select gpr.id,gpr.task_name, gpr.user_id, gpr.user_name, gpr.goods_category_id, gpr.goods_from, gpr.max_price, gpr.mid_price, gpr.min_Price, gpr.create_time, mgc.name as goodsCategoryName, mgc.sequence as goodsCategorySequence, mgc.parent_id as goodsCategoryParentId from goods_pricing_record gpr left join market_goods_category mgc on (mgc.id = gpr.goods_category_id)
and gpr.create_time >= #{param.period.begin} and gpr.create_time < #{param.period.end}
and gpr.goods_category_id = #{param.goodsCategoryId}
and gpr.goods_category_Name like like concat('%',#{param.goodsCategoryName},'%')
and gpr.user_name like concat('%',#{param.name},'%')
